string Decorate(string text = "a" + "b", bool enabled = !false, int offset = -2147483648, long maximum = 9223372036854775807L) {
    return text + ":" + enabled + ":" + offset + ":" + maximum;
}
void Main() { Print(Decorate()); Print(Decorate(maximum: 7, text: "custom", offset: 2, enabled: false)); }
